INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(46511, 'Isaiah 41:4', 'Isaiah', 41, 4, 'هغه څوک ؤ چې سبب د دې کارو شو؟ هغه څوک دی چې له پیله په نسلونو کې خلک ټاکي خپل مقصد دپاره؟ زه څښتن وم موجود له پیل نه او په پای کې هم به یم موجود زه څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_4.mp3', '', 1761754199, 1761754199),
(46512, 'Isaiah 41:5', 'Isaiah', 41, 5, 'خلک د لېرې هېوادو وېریږي ځکه ليدلي دي هغوی زما کارونه لړزیږي ټوله نړۍ له وېرې هغوی راغلل او ټول راغونډ شول سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_5.mp3', '', 1761754199, 1761754199),
(46513, 'Isaiah 41:6', 'Isaiah', 41, 6, 'هغوی د یو بل سره مرسته کوي او وایي یو بل ته: ‹قوي اوسئ!›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_6.mp3', '', 1761754199, 1761754199),
(46514, 'Isaiah 41:7', 'Isaiah', 41, 7, 'نجار زرګر ته وایي: ‹شاباش!› څوک چې هواروي بت په ټکولو باندې څوک هڅوي هغه چې کار کوي له سندان سره وایي هغوی چې لیم کاري یې ښه ده او په مېخونو ټینګوي دغه بت چې راونه لویږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_7.mp3', '', 1761754199, 1761754199),
(46515, 'Isaiah 41:8', 'Isaiah', 41, 8, 'خو ته ای د اسراییلو قومه، خدمتګاره زما ای یعقوبه چې غوره کړی یې ما ای زما د ملګري ابراهیم اولادې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_8.mp3', '', 1761754199, 1761754199),
(46516, 'Isaiah 41:9', 'Isaiah', 41, 9, 'د نړۍ له بله سره مې ته راوستلې د نړۍ د لېرې کنجونو مې راوغوښتلې او درته مې وویل: ‹ته خدمتګار یې زما ته مې رد کړی نه یې بلکې غوره کړی مې یې›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_9.mp3', '', 1761754199, 1761754199),
(46517, 'Isaiah 41:10', 'Isaiah', 41, 10, 'مه وېرېږه، ځکه یمه زه له تا سره مه ډارېږه، زه ستا خدای یم زه به تاته قوت درکړم، وبه کړم درسره مرسته زه به درکړم بری خپل عدالت کې او تا به ژغورم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_10.mp3', '', 1761754199, 1761754199),
(46518, 'Isaiah 41:11', 'Isaiah', 41, 11, 'ګوره، څوک چې په تا باندې په قهر دي ډېر ټول به وشرمیږي او رسوا به شي څوک چې کوي جګړه له تا سره په نشت حساب به شي هغوی او له منځه لاړ به شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_11.mp3', '', 1761754199, 1761754199),
(46519, 'Isaiah 41:12', 'Isaiah', 41, 12, 'هغه کسان چې کړي له تا سره جنګ لټوئ به هغوی تاسو خو پیدا به یې نه کړئ نور به نه وي هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_12.mp3', '', 1761754199, 1761754199),
(46520, 'Isaiah 41:13', 'Isaiah', 41, 13, 'ځکه زه یمه ستا څښتن خدای او تا نیسم له ښي لاسه او درته وایم: ‹مه وېرېږه، زه کوم تا سره مرسته›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_13.mp3', '', 1761754199, 1761754199),
(46521, 'Isaiah 41:14', 'Isaiah', 41, 14, 'څښتن وایي: «ای یعقوبه، ای اسراییله که څه هم ته یې کمزوری او کوچنی لکه چینجي په شان یې خو مه وېرېږه، زه یمه ستا مرستندوی د اسراییلو سپېڅلی خدای دی ستا ژغورونکی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_14.mp3', '', 1761754199, 1761754199),
(46522, 'Isaiah 41:15', 'Isaiah', 41, 15, 'ګوره، زه به جوړ کړمه له تا نه د درمند ټکولو څپر چې ولري نوي او تېره غاښونه ترڅو میده میده او هوار کړې غرونه او ذرې ذرې کړې غونډۍ ګانې لکه د بوسو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_15.mp3', '', 1761754199, 1761754199),
(46523, 'Isaiah 41:16', 'Isaiah', 41, 16, 'ته به هوا ته کړې ګوزار هغوی باد به یې لېرې یوسي او خواره واره به یې کړي توفان بیا به له ما څښتن خوشحاله شې او کوې به فخر په ما چې سپېڅلی خدای یمه د اسراییلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_16.mp3', '', 1761754199, 1761754199),
(46524, 'Isaiah 41:17', 'Isaiah', 41, 17, 'چې کله اوبه لټوي بې وزلي او مجبور خلک او نه پیدا کیږي هغه له ډېرې تندې یې وچیږي ستوني بیا زه څښتن به کړم قبوله د هغوی دعا هغوی به هېڅکله پرېنږدمه یوازې، زه د اسراییلو خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_17.mp3', '', 1761754199, 1761754199),
(46525, 'Isaiah 41:18', 'Isaiah', 41, 18, 'زه به سیندونه کړم جاري د وچو غرونو منځ کې او په درو کې به جاري کړم چینې زه به بدله کړمه دښته په ډنډونو د اوبو او کړم به بدله وچه ځمکه په جاري چینو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_18.mp3', '', 1761754199, 1761754199),
(46526, 'Isaiah 41:19', 'Isaiah', 41, 19, 'زه به راشنې کړمه په دښته کې د سبر او د اکاسۍ، اس او د زیتونو ونې کړم به صحرا کې راشنه د سروې او چنار او د نښتر ونې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_19.mp3', '', 1761754199, 1761754199),
(46527, 'Isaiah 41:20', 'Isaiah', 41, 20, 'ترڅو خلک وویني دا وبه کړي فکر په دې اړه او ټول به پوه شي په دې چې ما څښتن کړی دا کار په خپل قدرت باندې او سپېڅلي خدای د اسراییلو پیدا کړي دا ټول»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_20.mp3', '', 1761754199, 1761754199),
(46528, 'Isaiah 41:21', 'Isaiah', 41, 21, 'څښتن، د یعقوب پاچا وایي: «ای بتانو د قومونو، خپله دعوه وړاندې کړئ او ووایئ خپل قوي دلایل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_21.mp3', '', 1761754199, 1761754199),
(46529, 'Isaiah 41:22', 'Isaiah', 41, 22, 'هغوی دې وړاندې دلیلونه کړي او مونږ ته ووایي چې څه به پېښ شي او ودې وایي هغه پېښې چې پېشګویي یې کړې وه د پېښېدو نه مخکې راځئ چې وکړو فکر د هغو په هکله چې دا پېښ شوي په رښتیا دي که نه یا دې مونږ ته کړي بیان راتلونکی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_22.mp3', '', 1761754199, 1761754199),
(46530, 'Isaiah 41:23', 'Isaiah', 41, 23, 'مونږ ته ووایئ چې څه به کیږي په راتلونکې کې بیا به مونږ پوه شو چې په رښتیا تاسو خدایان یئ یا کوم کار وکړئ د خیر یا کوم مصیبت راولئ چې مونږ یې ووینو او ووېرېږو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_23.mp3', '', 1761754199, 1761754199),
(46531, 'Isaiah 41:24', 'Isaiah', 41, 24, 'خو تاسو هېڅ شی نه یئ او نه شئ کولای کوم کار چې غوره کوي تاسو څوک، د کرکې وړ دي هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_24.mp3', '', 1761754199, 1761754199),
(46532, 'Isaiah 41:25', 'Isaiah', 41, 25, 'ما هڅولی یو سړی چې حمله وکړي له شماله هغه ما دی غوره کړی له ختیځه هغه کوي زما د نوم درناوی او پاچاهان به کړي تر پښو لاندې لکه په خټو باندې خېژي چې کلال', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_25.mp3', '', 1761754199, 1761754199),
(46533, 'Isaiah 41:26', 'Isaiah', 41, 26, 'کړې وه چا دا پېشګویي چې به داسې کیږي ترڅو وکړو مونږ باور چې هغه وایي رښتیا؟ هېچا نه دي څه ویلي په دې اړه او نه یې کړی دی اعلان د دې ستاسو خبرې اورېدلې نه دي هیچا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_26.mp3', '', 1761754199, 1761754199),
(46534, 'Isaiah 41:27', 'Isaiah', 41, 27, 'زه څښتن وم لومړنی ذات چې مې صهیون ته ورکړ زېری ما استازی ولېږلو اورشلیم ته چې هلته ووایي: ‹وګورئ، راروان دي ستاسو خلک›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_27.mp3', '', 1761754199, 1761754199),
(46535, 'Isaiah 41:28', 'Isaiah', 41, 28, 'خو ما پیدا نه کړلو څوک د هغو خدایانو منځ کې چې راکړي ماته مشوره او په هغو کې یو هم رانه کړ ځواب زما د پوښتنې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_28.mp3', '', 1761754199, 1761754199),
(46536, 'Isaiah 41:29', 'Isaiah', 41, 29, 'ګورئ، دا ټول دي دروغجن خدایان هغوی هېڅ شی هم کولای نه شي دا دي بې وسه او کمزوري بتان»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_29.mp3', '', 1761754199, 1761754199),
(46537, 'Job 24:1', 'Job', 24, 1, 'قادر خُدائ د عدالت دپاره وخت ولې نۀ مقرروى؟ او د خُدائ پاک منونکى دا ولې نۀ ګورى چې هغه د ګناهګارانو عدالت کوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_1.mp3', '', 1761754199, 1761754199),
(46538, 'Job 24:2', 'Job', 24, 2, 'بدعمله کسان د حد د پولې کاڼى لرې کوى، هغوئ څاروى پټ کړى او د خپلو رَمو سره يې څروى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_2.mp3', '', 1761754199, 1761754199),
(46539, 'Job 24:3', 'Job', 24, 3, 'هغوئ د يتيم خر بوځى، او هغوئ د کونډې غوَيے په ضمانت کښې بوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_3.mp3', '', 1761754199, 1761754199),
(46540, 'Job 24:4', 'Job', 24, 4, 'هغوئ ضرورتمند د سړک نه ديکه کوى، او غريبانان دې ته مجبوروى چې ځان پټ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_4.mp3', '', 1761754199, 1761754199),
(46541, 'Job 24:5', 'Job', 24, 5, 'غريبانان لکه د ځنګلى خرونو په شان په صحرا کښې خوراک لټوى، هغوئ د خپلو بچو دپاره په بل ځائ کښې خوراک نۀ شى پېدا کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_5.mp3', '', 1761754199, 1761754199),
(46542, 'Job 24:6', 'Job', 24, 6, 'هغوئ پردے پټے رېبى او هغوئ د بدعمله خلقو د انګورو په باغونو کښې پاتې شوى انګور راټولوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_6.mp3', '', 1761754199, 1761754199),
(46543, 'Job 24:7', 'Job', 24, 7, 'په يخنۍ کښې هغوئ ټوله شپه بربنډ پراتۀ وى، او په ځان اچولو دپاره ورسره هيڅ هم نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_7.mp3', '', 1761754199, 1761754199),
(46544, 'Job 24:8', 'Job', 24, 8, 'هغوئ په غرونو کښې په بارانونو سره لامدۀ وى، او په کاڼو کښې پناه اخلى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_8.mp3', '', 1761754199, 1761754199),
(46545, 'Job 24:9', 'Job', 24, 9, 'بدعمله خلق د کونډې ماشوم د تى نه په زور لرې کوى، او د غريب ماشوم په ضمانت کښې يوسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_9.mp3', '', 1761754199, 1761754199),
(46546, 'Job 24:10', 'Job', 24, 10, 'غريبانان د جامو نه بغېر بربنډ ګرځى، او په نهَرو کولمو د خلقو رېبلے شوى ګېډى اوړى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_10.mp3', '', 1761754199, 1761754199),
(46547, 'Job 24:11', 'Job', 24, 11, 'د زيتُونو د ونو نه تېل وباسى خو د څَکلو اجازت ورته نۀ وى، هغوئ انګور نچوړوى خو په خپله تږى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_11.mp3', '', 1761754199, 1761754199),
(46548, 'Job 24:12', 'Job', 24, 12, 'چې څوک مرى د هغوئ فريادونه په ښار کښې اورېدے شى، او مالدار خلق چې غريبانانو سره کوم ظلم زياتے کوى نو خُدائ پاک ورته هيڅ توجو نۀ ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_12.mp3', '', 1761754199, 1761754199),
(46549, 'Job 24:13', 'Job', 24, 13, 'هلته هغه څوک دى کوم چې د رڼا خِلاف بغاوت کوى، او هغوئ د دې روښانه لارې نه خبر نۀ دى نو ځکه هغوئ بې‌لارې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_13.mp3', '', 1761754199, 1761754199),
(46550, 'Job 24:14', 'Job', 24, 14, 'قاتِل سحر وختى راپاڅى چې غريب او ضرورتمند ووژنى، او په تيارۀ کښې غلا کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_14.mp3', '', 1761754199, 1761754199),
(46551, 'Job 24:15', 'Job', 24, 15, 'زناکار هم د تيارې په اِنتظار کښې وى، خيال يې دا وى چې د هيچا به په ما باندې نظر نۀ وى، او هغه مخ پټوى چې څوک مې ونۀ پېژنى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_15.mp3', '', 1761754199, 1761754199),
(46552, 'Job 24:16', 'Job', 24, 16, 'د شپې په وخت کښې غلۀ د کورونو کنډرې کوى، او د ورځې خوبونه کوى، او رڼا ته نۀ راوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_16.mp3', '', 1761754199, 1761754199),
(46553, 'Job 24:17', 'Job', 24, 17, 'ځکه چې توره شپه د هغوئ دپاره سحر دے، او هغوئ د تورې تيارې د يرې سره عادت دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_17.mp3', '', 1761754199, 1761754199),
(46554, 'Job 24:18', 'Job', 24, 18, 'هغوئ د اوبو په سر د زګ په شان فانى وى، د هغوئ په زمکه لعنت وئيلے شوے دے نو په دې وجه خلق د انګورو باغونو ته نۀ ځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_18.mp3', '', 1761754199, 1761754199),
(46555, 'Job 24:19', 'Job', 24, 19, 'قبر ګناه ګار داسې غېبوى لکه چې اوچ کالى او ګرمى واوره غېبوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_19.mp3', '', 1761754199, 1761754199),
(46556, 'Job 24:20', 'Job', 24, 20, 'د هغوئ خپله مور به هغوئ هېر کړى، او چينجو ته به هغوئ خواږۀ ښکاره شى، او نور به څوک هغوئ نۀ يادوى، نو بدعمله خلق داسې راپرېوځى لکه چې په طوفان کښې ونه راپرېوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_20.mp3', '', 1761754199, 1761754199),
(46557, 'Job 24:21', 'Job', 24, 21, 'هغوئ د بې‌اولاده مور سره ټګى کوى، او د کونډې سره ښۀ نۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_21.mp3', '', 1761754199, 1761754199),
(46558, 'Job 24:22', 'Job', 24, 22, 'خو خُدائ پاک طاقتور خلق د خپل قوت سره برباد کړى، کېدے شى چې هغوئ د لږ وخت دپاره کامياب شى خو د هغوئ ژوند څۀ اعتبارى نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_22.mp3', '', 1761754199, 1761754199),
(46559, 'Job 24:23', 'Job', 24, 23, 'کېدے شى چې هغه ورله امن ورکړى چې په حِفاظت سره ژوند تېروى، خو هغوئ د خُدائ پاک د نظر لاندې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_23.mp3', '', 1761754199, 1761754199),
(46560, 'Job 24:24', 'Job', 24, 24, 'د لږ وخت دپاره بدعمله مالداره وى، خو هغوئ بيا د واښو په شان اوچ شى، هغوئ د فصل د سرونو په شان پرې کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_24.mp3', '', 1761754199, 1761754199),
(46561, 'Job 24:25', 'Job', 24, 25, 'کۀ داسې نۀ وى نو څوک به ما دروغژن ثابت کړى، او چې ښکاره کړى چې زۀ څۀ وايم نو هغه تشې خبرې دى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job24_verse_25.mp3', '', 1761754199, 1761754199),
(46562, 'Job 13:1', 'Job', 13, 1, 'ګوره، زما سترګو دا هر څۀ ليدلى دى، او زما غوږُونو دا اورېدلى دى او پوهه شوے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_1.mp3', '', 1761754199, 1761754199),
(46563, 'Job 13:2', 'Job', 13, 2, 'چې تا ته د څۀ پته ده نو ما ته هم د هغې پته ده، زۀ تا نه څۀ کم نۀ يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_2.mp3', '', 1761754199, 1761754199),
(46564, 'Job 13:3', 'Job', 13, 3, 'خو زۀ به د قادر خُدائ سره خبره وکړم، او زۀ غواړم چې هغۀ ته خپل ځان بې‌ګناه ثابت کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_3.mp3', '', 1761754199, 1761754199),
(46565, 'Job 13:4', 'Job', 13, 4, 'د حقيقت پټولو دپاره تاسو دروغ وايئ، او تاسو د بې‌کاره طبيبانو په شان يئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_4.mp3', '', 1761754199, 1761754199),
(46566, 'Job 13:5', 'Job', 13, 5, 'مړه کۀ تاسو خولې بندې کړئ، نو دا به ستاسو عقلمندى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_5.mp3', '', 1761754199, 1761754199),
(46567, 'Job 13:6', 'Job', 13, 6, 'اوس تاسو زما بحث واورئ، او زما زارۍ واورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_6.mp3', '', 1761754199, 1761754199),
(46568, 'Job 13:7', 'Job', 13, 7, 'تاسو هغه څۀ وايئ څۀ چې خُدائ پاک نۀ دى وئيلى، او تاسو د هغۀ د خاطره د دوکې خبرې کوئ څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_7.mp3', '', 1761754199, 1761754199),
(46569, 'Job 13:8', 'Job', 13, 8, 'تاسو به د هغۀ طرفدارى کوئ څۀ، تاسو به د خُدائ پاک صفائى کوئ څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_8.mp3', '', 1761754199, 1761754199),
(46570, 'Job 13:9', 'Job', 13, 9, 'دا به ستاسو دپاره ښۀ وى څۀ چې هغه ستاسو آزمېښت وکړى؟ يا تاسو هغه داسې دوکه کولے شئ، لکه چې تاسو نور کسان دوکه کوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_9.mp3', '', 1761754199, 1761754199),
(46571, 'Job 13:10', 'Job', 13, 10, 'هغه به بې‌شکه تاسو ورَټى کۀ تاسو په پټه طرفدارى وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_10.mp3', '', 1761754199, 1761754199),
(46572, 'Job 13:11', 'Job', 13, 11, 'د هغۀ د شان نه به تاسو يرېږئ نه څۀ، او د هغۀ يره به په تاسو باندې غالبه نۀ شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_11.mp3', '', 1761754199, 1761754199),
(46573, 'Job 13:12', 'Job', 13, 12, 'ستاسو قيصې او متلونه د ايرو په شان بې‌کاره دى، او ستاسو خبرې د خټې د لوښو په شان کچه دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_12.mp3', '', 1761754199, 1761754199),
(46574, 'Job 13:13', 'Job', 13, 13, 'تاسو غلى شئ او ما له د خبرو کولو موقع راکړئ، نو چې څۀ کيږى هغه دې په ما وشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_13.mp3', '', 1761754199, 1761754199),
(46575, 'Job 13:14', 'Job', 13, 14, 'زۀ به خپل ژوند په خطره کښې واچوم، او د خپل زړۀ خبره به وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_14.mp3', '', 1761754199, 1761754199),
(46576, 'Job 13:15', 'Job', 13, 15, 'کۀ هغه ما وژنى هم خو زۀ به په هغۀ توکل کوم، او زۀ به د هغۀ په مخکښې خپله دفاع کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_15.mp3', '', 1761754199, 1761754199),
(46577, 'Job 13:16', 'Job', 13, 16, 'او داسې به زۀ بچ شم ځکه چې زۀ څۀ کافر خو نۀ يم کۀ زۀ وم نو بيا به زۀ د هغۀ په مخکښې نۀ شوم ودرېدے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_16.mp3', '', 1761754199, 1761754199),
(46578, 'Job 13:17', 'Job', 13, 17, 'زما خبره په غور سره واورئ، او تاسو ما ته غوږ ونيسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_17.mp3', '', 1761754199, 1761754199),
(46579, 'Job 13:18', 'Job', 13, 18, 'ګورئ، ما د خپلې خبرې تيارے کړے دے، ما ته پته ده چې زۀ به بې‌ګناه ثابت شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_18.mp3', '', 1761754199, 1761754199),
(46580, 'Job 13:19', 'Job', 13, 19, 'څوک ما سره په دې باندې بحث کولے شى؟ کۀ څوک ما غلط ثابت کړى نو زۀ به خاموش شم او مړ به شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_19.mp3', '', 1761754199, 1761754199),
(46581, 'Job 13:20', 'Job', 13, 20, 'اے خُدايه، ما له صِرف دوه څيزونه راکړه، نو بيا به زۀ خپل ځان ستا نه نۀ پټوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_20.mp3', '', 1761754199, 1761754199),
(46582, 'Job 13:21', 'Job', 13, 21, 'خپله سزا زما نه لرې کړه، او په خپله يره باندې ما مۀ يروه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_21.mp3', '', 1761754199, 1761754199),
(46583, 'Job 13:22', 'Job', 13, 22, 'بيا ما ته آواز وکړه او زۀ به جواب درکړم، يا ما له اجازت راکړه چې خبرې وکړم او تۀ ما له د هغې جواب راکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_22.mp3', '', 1761754199, 1761754199),
(46584, 'Job 13:23', 'Job', 13, 23, 'زما غلطيانې او زما ګناهونه څومره دى؟ ما ته زما بغاوت او زما ګناه وښايه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_23.mp3', '', 1761754199, 1761754199),
(46585, 'Job 13:24', 'Job', 13, 24, 'تۀ خپل مخ ولې پټوې، او تۀ ما خپل دشمن ولې ګڼې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_24.mp3', '', 1761754199, 1761754199),
(46586, 'Job 13:25', 'Job', 13, 25, 'زۀ خو هيڅ هم نۀ يم، نو تۀ ما ولې يروې؟ زۀ خو داسې يم لکه چې په هوا کښې پاڼې خوَزى دوړې الوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_25.mp3', '', 1761754199, 1761754199),
(46587, 'Job 13:26', 'Job', 13, 26, 'ځکه چې تۀ زما خِلاف ترخې خبرې ليکې، او تۀ ما له د ځوانۍ د ګناه سزا راکوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_26.mp3', '', 1761754199, 1761754199),
(46588, 'Job 13:27', 'Job', 13, 27, 'تۀ زما پښې په زولنو کښې تړې، او تۀ زما په ټول چال چلن نظر ساتې، او زما د پښو چاپونه هم معلوموې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_27.mp3', '', 1761754199, 1761754199),
(46589, 'Job 13:28', 'Job', 13, 28, 'زۀ د سخا څيزونو په شان خراب شوے يم، د هغه جامو په شان چې چينجو خوړلې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job13_verse_28.mp3', '', 1761754199, 1761754199),
(46590, 'Esther 7:1', 'Esther', 7, 1, 'نو پاچا او هامان د ډوډۍ خوړلو دپاره د استر مېلمستیا ته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther7_verse_1.mp3', '', 1761754199, 1761754199),
(46591, 'Esther 7:2', 'Esther', 7, 2, 'د دوهم ځل دپاره چې هغوی شراب څښل، پاچا بیا پوښتنه وکړه: «ای استر ملکې، ته څه غواړې؟ هغه به درکړل شي. ستا غوښتنه څه ده؟ که ته وغواړې، زه به حتی نیمه امپراتوري هم درکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther7_verse_2.mp3', '', 1761754199, 1761754199),
(46592, 'Esther 7:3', 'Esther', 7, 3, 'استر ملکې په ځواب کې وویل: «ای پاچا! که تاسو په ما باندې مهرباني کوئ او که چېرې ستاسو خوښه وي، نو بیا زما ژوند وژغورئ. دا زما غوښتنه ده. او زما د قوم ژوند هم وژغورئ. دا زما هیله ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther7_verse_3.mp3', '', 1761754199, 1761754199),
(46593, 'Esther 7:4', 'Esther', 7, 4, 'ځکه چې زه او زما قوم په بې رحمۍ سره د وژلو دپاره خرڅ شوي یو. که چېرې یوازې د غلامانو او وینځو په شان خرڅ شوي وای، نو زه به غلې پاتې شوې وای او په دې هکله به مې تاسو نه په تکلیف کولئ. خو مونږ د وژلو او نابودۍ سره مخامخ یو!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther7_verse_4.mp3', '', 1761754199, 1761754199),
(46594, 'Esther 7:5', 'Esther', 7, 5, 'خشایار پاچا د استر ملکې نه پوښتنه وکړه: «هغه څوک دی؟ هغه سړی چېرته دی چې د داسې کار جرات لري؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther7_verse_5.mp3', '', 1761754199, 1761754199),
(46595, 'Esther 7:6', 'Esther', 7, 6, 'استر ځواب ورکړ: «زمونږ دښمن او زمونږ ځوروونکی همدا بد سړی هامان دی!» په دې وخت کې هامان د پاچا او ملکې نه ډېر ووېرېد.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther7_verse_6.mp3', '', 1761754199, 1761754199),
(46596, 'Esther 7:7', 'Esther', 7, 7, 'پاچا په ډېر قهر سره د مېلمستیا نه پاڅېد او د ماڼۍ باغ ته لاړ. هامان پوه شو چې پاچا د هغه د اعدامولو اراده کړې ده، نو هغه په کوټه کې پاتې شو چې استر ملکې ته د خپل ژوند په خاطر زارۍ وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther7_verse_7.mp3', '', 1761754199, 1761754199),
(46597, 'Esther 7:8', 'Esther', 7, 8, 'هامان د استر په تخت باندې ځان وغورځاوه چې هغې ته د رحم دپاره زارۍ وکړي. په دې وخت کې پاچا بېرته د مېلمستیا سالون ته راستون شو او هامان یې د استر په تخت باندې ولیده. پاچا چیغې کړې: «ایا دا سړی همدلته زما په مخکې زما خپلې ماڼۍ کې ملکه بې عزته کوي؟» څنګه چې د پاچا د خولې نه دا خبره راووتله، خصیانو د هامان مخ پټ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther7_verse_8.mp3', '', 1761754199, 1761754199),
(46598, 'Esther 7:9', 'Esther', 7, 9, 'په دې وخت کې حربونه چې د پاچا د خصیانو د ډلې څخه ؤ او د هغه خدمت یې کاوه، وویل: «هامان په خپل کور کې د درویشت مترو په لوړوالي یو دار جوړ کړی دی، ترڅو مردخای چې ستاسو اعلیحضرت ژوند یې ژغورلی دی، په هغه باندې وځړوي.» پاچا امر وکړ: «هامان په هغه باندې وځړوئ!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther7_verse_9.mp3', '', 1761754199, 1761754199),
(46599, 'Esther 7:10', 'Esther', 7, 10, 'نو هامان په هغه دار باندې چې هغه د مردخای دپاره جوړ کړی ؤ، وځړول شو. بیا د پاچا قهر سوړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther7_verse_10.mp3', '', 1761754199, 1761754199),
(46600, 'Joshua 17:1', 'Joshua', 17, 1, 'د ځمکې یوه برخه چې د اردن د سیند په لوېدیځ کې وه، ځینو کورنیو ته چې د یوسف د مشر زوی منسي اولاده وه ورکړل شوه. ماخیر د جلعاد پلار ؤ او د منسي مشر زوی ؤ. ماخیر یو نظامي اتل ؤ، نو د اردن د سیند په ختیځ کې د جلعاد او باشان سیمې هغه ته ورکړل شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_1.mp3', '', 1761754199, 1761754199),
(46601, 'Joshua 17:2', 'Joshua', 17, 2, 'د اردن د سیند په لوېدیځ کې د منسي پاتې کورنیو ته ځمکه ورکړل شوه چې هغه کورنۍ دا وې: ابیعزر، هالک، اسري ییل، شکیم، حافر او شمیداع. دا د یوسف د زوی یعنې منسي نارینه اولاده وه او هغوی د کورنیو مشران وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_2.mp3', '', 1761754199, 1761754199),
(46602, 'Joshua 17:3', 'Joshua', 17, 3, 'د منسي لمسي جلعاد یو زوی درلود چې حافر نومېده. حافر یو زوی درلود چې صلفحاد نومېده او هغه هېڅ زامن نه درلودل، خو پنځه لورګانې یې درلودلې چې نومونه یې دا وو: محله، نوعه، حجله، ملکه او ترزه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_3.mp3', '', 1761754199, 1761754199),
(46603, 'Joshua 17:4', 'Joshua', 17, 4, 'هغوی العازار کاهن، د نون زوی یوشع او مشرانو ته ورغلې او ویې ویل: «څښتن موسی ته ویلي دي چې صلفحاد هېڅ زامن نه لري. نو د هغه هرې لور ته د ځمکې یوه برخه ورکړه.» یوشع د څښتن د حکم څخه اطاعت وکړ. هغه د صلفحاد لورګانو ته د هغوی د نارینه خپلوانو په شان ځمکه ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_4.mp3', '', 1761754199, 1761754199),
(46604, 'Joshua 17:7', 'Joshua', 17, 7, 'د منسي سیمه د اشیر څخه تر مکمیته پورې رسېدله. مکمیته د شکیم په ختیځ کې وه او سرحد یې بیا جنوب خواته هغه ځای ته چې د عین تفوح خلک په کې اوسېدل، رسېدلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_7.mp3', '', 1761754199, 1761754199),
(46605, 'Joshua 17:8', 'Joshua', 17, 8, 'د تفوح ښارګوټی د منسي او افرایم د سیمو ترمنځ په سرحد کې پروت ؤ. په خپله ښار د افرایم د قبیلې ؤ، خو د هغه شاوخوا ځمکه د منسي د قبیلې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_8.mp3', '', 1761754199, 1761754199),
(46606, 'Joshua 17:9', 'Joshua', 17, 9, 'دا سرحد بیا ښکته د قانه خوړ ته تللی دی. کوم ښارګوټي چې د خوړ په جنوب کې وو هغه د افرایم شول، که څه هم هغه د منسي په سیمه کې وو. د منسي سرحد د خوړ په شمالي خوا باندې تېر شوی او د مدیترانې په بحیره کې ختم شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_9.mp3', '', 1761754199, 1761754199),
(46607, 'Joshua 17:10', 'Joshua', 17, 10, 'افرایم په جنوب کې پروت ؤ او منسي په شمال کې. د مدیترانې بحیره د هغوی لوېدیځ سرحد ؤ. اشیر په شمال لوېدیځ کې پروت ؤ او یساکار په شمال ختیځ کې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_10.mp3', '', 1761754199, 1761754199),
(46608, 'Joshua 17:11', 'Joshua', 17, 11, 'د یساکار او اشیر په سیمو کې منسي بیت شان او یبلعام د هغو د شاوخوا کلیو سره او همدارنګه دور (هغه دور چې په غونډیو باندې ؤ)، عین دور، تعنک، مجدو او د هغو شاوخوا کلي تر لاسه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_11.mp3', '', 1761754199, 1761754199),
(46609, 'Joshua 17:12', 'Joshua', 17, 12, 'بیاهم منسیانو نه شو کولای هغه کنعانیان وشړي چې په دې ښارګوټو کې اوسېدل، نو هغوی هلته اوسېدلو ته دوام ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_12.mp3', '', 1761754199, 1761754199),
(46610, 'Joshua 17:13', 'Joshua', 17, 13, 'که څه هم کله چې اسراییلیان نور هم قوي شول، کنعانیان یې په سخت کار کولو باندې مجبور کړل، خو بیخي یې ونه شړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_13.mp3', '', 1761754199, 1761754199);